import{_ as a,o as n,c as s,a0 as t}from"./chunks/framework.CKZJaUMN.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),o={name:"explanation/architecture.md"};function i(p,e,r,c,d,l){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Hypha is the <em>substrate</em> layer: distributed primitives over generic entities. It owns who may act on an entity, when, and on which machine — plus the transport that gets ops and snapshots there.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                 ┌─────────────── hypha-hub ───────────────┐</span></span>
<span class="line"><span>                 │  merged index · op routing · push · SSE  │</span></span>
<span class="line"><span>                 └──────────────┬───────────────┬──────────┘</span></span>
<span class="line"><span>                        HTTP+SSE │               │ HTTP+SSE</span></span>
<span class="line"><span>                  ┌──────────────▼──┐    ┌───────▼──────────┐</span></span>
<span class="line"><span>                  │ hypha node A    │    │ hypha node B     │</span></span>
<span class="line"><span>                  │ /api/entities*  │    │ /api/entities*   │</span></span>
<span class="line"><span>                  │ KindRegistry    │    │ KindRegistry     │</span></span>
<span class="line"><span>                  └───────┬─────────┘    └────────┬─────────┘</span></span>
<span class="line"><span>                          │  integrations register entity planes:</span></span>
<span class="line"><span>              ┌───────────┼───────────────────────┼───────────┐</span></span>
<span class="line"><span>              ▼           ▼                       ▼           ▼</span></span>
<span class="line"><span>        sepia-session  campaign-run          &lt;kind-N&gt;     entity.*</span></span>
<span class="line"><span>        (sepia repo)   (peregrin repo)       (any repo)   (substrate)</span></span></code></pre></div><h2 id="planes" tabindex="-1">Planes <a class="header-anchor" href="#planes" aria-label="Permalink to &quot;Planes&quot;">​</a></h2><ul><li><strong>Entity plane</strong> — this repo: <code>EntityApi</code> contract (<code>hypha-node-api</code>), node host (<code>hypha serve</code>, <code>hypha-node</code> + <code>hypha-http</code>), hub gateway (<code>hypha-hub</code>), projection (<code>hypha-sync</code>), outbox (<code>hypha-outbox</code>), arbitration (<code>hypha-control</code>), push.</li><li><strong>Integration planes</strong> — one per workload kind, living in the workload&#39;s own repo: <code>sepia-peregrin</code> (sepia repo) registers <code>kind=&quot;sepia-session&quot;</code>; peregrin registers <code>kind=&quot;campaign&quot;</code>. An integration translates entity ops ↔ its verbs and implements snapshot as its own serialize/resume.</li><li><strong>Orchestration plane</strong> — campaigns, drivers, loaders. Stays in peregrin; becomes a <em>workload on</em> hypha rather than a peer of it.</li></ul><h2 id="ports-and-adapters" tabindex="-1">Ports and adapters <a class="header-anchor" href="#ports-and-adapters" aria-label="Permalink to &quot;Ports and adapters&quot;">​</a></h2><p>Every I/O seam is a port (<code>hypha-secret</code>, <code>hypha-service</code>, …) with impls behind it (<code>-keyring</code>, <code>-dotenv</code>, <code>-systemd</code>). The substrate contracts are pure — <code>hypha-control</code> has no I/O at all.</p><h2 id="dataflow" tabindex="-1">Dataflow <a class="header-anchor" href="#dataflow" aria-label="Permalink to &quot;Dataflow&quot;">​</a></h2><p>Client → hub <code>POST /api/entities/{id}/ops</code> → lock gate (<code>hypha-control</code>) → owner node <code>POST /api/entities/{id}/ops</code> → the kind&#39;s <code>EntityPlane::op</code>. Node down? <code>hypha-outbox</code> FIFO per entity, replayed oldest-first on reconnect. Reads merge through <code>hypha-sync</code>&#39;s SQLite projection + SSE diff tail.</p>`,9)])])}const y=a(o,[["render",i]]);export{u as __pageData,y as default};
